import { test, expect } from '@playwright/test';

test.describe('Async Operation Cancellation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <html>
        <body>
          <button id="startBtn">Start Operation</button>
          <button id="abortBtn" disabled>Abort</button>
          <div id="status">Ready</div>
          <div id="result"></div>
          <script>
            let abortController = null;

            document.getElementById('startBtn').addEventListener('click', async () => {
              abortController = new AbortController();
              const startBtn = document.getElementById('startBtn');
              const abortBtn = document.getElementById('abortBtn');
              const status = document.getElementById('status');
              const result = document.getElementById('result');

              startBtn.disabled = true;
              abortBtn.disabled = false;
              status.textContent = 'Operation in progress...';
              result.textContent = '';

              try {
                const response = await fetch('https://httpbin.org/delay/10', {
                  signal: abortController.signal
                });
                const data = await response.json();
                status.textContent = 'Operation completed';
                result.textContent = 'Success: Operation finished';
              } catch (error) {
                if (error.name === 'AbortError') {
                  status.textContent = 'Operation cancelled';
                  result.textContent = 'Cancelled: Operation was aborted by user';
                } else {
                  status.textContent = 'Operation failed';
                  result.textContent = 'Error: ' + error.message;
                }
              } finally {
                startBtn.disabled = false;
                abortBtn.disabled = true;
              }
            });

            document.getElementById('abortBtn').addEventListener('click', () => {
              if (abortController) {
                abortController.abort();
              }
            });
          </script>
        </body>
      </html>
    `);
  });

  test('should start async operation and display in-progress status', async ({ page }) => {
    const startButton = page.getByRole('button', { name: 'Start Operation' });
    const statusDiv = page.locator('#status');

    await startButton.click();

    await expect(statusDiv).toContainText('Operation in progress...');
    await expect(startButton).toBeDisabled();
  });

  test('should cancel async operation when abort button is clicked', async ({ page }) => {
    const startButton = page.getByRole('button', { name: 'Start Operation' });
    const abortButton = page.getByRole('button', { name: 'Abort' });
    const statusDiv = page.locator('#status');
    const resultDiv = page.locator('#result');

    await startButton.click();

    await expect(abortButton).toBeEnabled();

    await abortButton.click();

    await expect(statusDiv).toContainText('Operation cancelled');
    await expect(resultDiv).toContainText('Cancelled: Operation was aborted by user');
    await expect(abortButton).toBeDisabled();
    await expect(startButton).toBeEnabled();
  });

  test('should disable abort button after operation completes', async ({ page }) => {
    const startButton = page.getByRole('button', { name: 'Start Operation' });
    const abortButton = page.getByRole('button', { name: 'Abort' });

    await startButton.click();

    await expect(abortButton).toBeEnabled();

    await page.waitForTimeout(500);

    await expect(abortButton).toBeEnabled();
  });

  test('should re-enable start button after abort', async ({ page }) => {
    const startButton = page.getByRole('button', { name: 'Start Operation' });
    const abortButton = page.getByRole('button', { name: 'Abort' });

    await startButton.click();
    await expect(startButton).toBeDisabled();

    await abortButton.click();

    await expect(startButton).toBeEnabled();
  });
});
